#!/usr/bin/env python3
"""One TEST-only staff workflow update. Does not send, create events or change booking rows."""
import base64
import fcntl
import hashlib
import json
import os
from pathlib import Path
import pwd
import re
import sqlite3
import stat
import subprocess
import sys
import tempfile
import types
import zlib

RELEASE = 'booking-workflow-20260927'
REVISION = '20260927-r1'
BASE = ''
BASE_SHA = 'e2aec7421498e4a3c9fd214f40bdbb613b0da3a4ffbea90926497d015f575e57'
BUNDLE = ''
BUNDLE_SHA = '2ca81b911da20d92bb21068ecff5f34f7bd9382de06d019456ebfe0dde0c2cf1'
NAMES = ('server/booking-workflow.php', 'server/booking-staff.php')
CONTROLLER = NAMES[-1]
JOURNAL = 'booking-workflow-install.json'
MANIFESTS = ('calendar-confirmation-release.json', 'microsoft-scheduling-release.json', 'booking-workflow-release.json')


def modules():
    raw = zlib.decompress(base64.b64decode(BASE))
    if hashlib.sha256(raw).hexdigest() != BASE_SHA:
        raise RuntimeError('Base integrity differs.')
    s = types.ModuleType('reviewed_scheduling')
    s.__file__ = __file__
    exec(compile(raw, 'reviewed-scheduling', 'exec'), s.__dict__)
    r, m = s.modules()
    return s, r, m


def bundle(m):
    raw = zlib.decompress(base64.b64decode(BUNDLE))
    m.need(m.digest(raw) == BUNDLE_SHA, 'Workflow payload integrity differs.')
    data = json.loads(raw)
    m.need(set(data['files']) == set(NAMES), 'Workflow package paths differ.')
    return {k:v.encode() for k,v in data['files'].items()}, data['before']


def database_check(s, m, root):
    s.database_check(m, root)
    db = sqlite3.connect('file:' + str(root/'data/bookings.sqlite') + '?mode=ro', uri=True, timeout=5)
    try:
        db.execute('PRAGMA query_only=ON')
        required = {
            'bookings': {'reference','email','status','deposit_paid_at','crm_contact_id','approved_at'},
            'booking_contact_links': {'reference','org_id','contact_id','email','verified_at'},
            'booking_communications': {'communication_key','reference','kind','submission_state','provider_message_id',
                'internet_message_id','sent_at','delivery_state','crm_state','crm_contact_id','crm_org_id'},
        }
        for table, columns in required.items():
            actual = {row[1] for row in db.execute('PRAGMA table_info(' + table + ')')}
            m.need(columns <= actual, 'Required existing database schema differs: ' + table + '; no database repair was attempted.')
    finally:
        db.close()


def inventory(s, r, m, root, php, uid, files, before, account=None, credentials=None):
    report = r.inventory(m, root, m.payload(), php, uid, account=account, credentials=credentials)
    baseline, _ = s.bundle(m)
    for name, expected in before.items():
        data = report.file(root/name)
        allowed = {expected}
        if name in files: allowed.add(m.digest(files[name]))
        if data is not None and m.digest(data) not in allowed:
            report.issue('Unreviewed application source preserved: ' + name)
        report.readable.add(root/name)
    helper = report.file(root/NAMES[0], optional=True)
    if helper is not None and helper != files[NAMES[0]]:
        report.issue('Existing workflow helper differs; preserved.')
    active = report.file(root/s.ACTIVATION, private=True)
    if active is not None and active != s.activation(m):
        report.issue('Microsoft TEST scheduling activation differs; no settings were changed.')
    report.readable.add(root/s.ACTIVATION)
    ms = report.json(root/'microsoft-scheduling-release.json', private=True)
    expected = {k:m.digest(v) for k,v in baseline.items()}
    updated = dict(expected); updated.update({k:m.digest(v) for k,v in files.items()})
    if ms is not None and (ms.get('release') != s.RELEASE or ms.get('files') not in (expected, updated)):
        report.issue('Microsoft scheduling release manifest differs; preserved.')
    workflow = report.json(root/MANIFESTS[-1], private=True, optional=True)
    if workflow is not None and workflow != {'release':RELEASE,'revision':REVISION,'files':{k:m.digest(v) for k,v in files.items()}}:
        report.issue('An unrelated workflow release is present; preserved.')
    crm = report.json(root/'zoho-crm.json', private=True)
    if crm is not None and not (all(isinstance(crm.get(k),str) and crm[k] for k in ('client_id','client_secret','refresh_token','org_id','user_id'))
            and re.fullmatch(r'[0-9]{1,30}', crm['org_id']) and re.fullmatch(r'[0-9]{1,30}', crm['user_id'])
            and crm.get('api_domain') == 'https://www.zohoapis.com' and crm.get('accounts_domain') == 'https://accounts.zoho.com'
            and crm.get('sync_mode') == 'api' and crm.get('original_sync_mode') == 'api'
            and crm.get('sync_reviewed_at') and crm.get('owner_verified_at')):
        report.issue('Established CRM identity/API email-association configuration differs; no credentials or settings were changed.')
    report.readable.add(root/'zoho-crm.json')
    mail = report.json(root/'booking-mail.json', private=True)
    if mail is not None and mail.get('enabled') is not True:
        report.issue('Existing TEST invitation delivery is not enabled; no setting was changed.')
    for name in ('zoho-calendar.json','zoho-confirmation.json'):
        config = report.json(root/name, private=True)
        if config is not None and (not re.fullmatch(r'[a-f0-9]{32}',str(config.get('calendar_uid',''))) or not config.get('enabled')):
            report.issue('Legacy appointment connection differs: ' + name)
        report.readable.add(root/name)
    report.guarded('Existing booking schema and reservations (read only)', lambda:database_check(s,m,root))
    with tempfile.TemporaryDirectory(prefix='sitesee-workflow-lint-') as folder:
        for name, content in files.items():
            def lint(name=name,content=content):
                path=Path(folder)/Path(name).name; path.write_bytes(content)
                p=subprocess.run([php,'-l',str(path)],stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=30)
                m.need(p.returncode==0,'PHP syntax failed: '+name)
            report.guarded('Workflow syntax',lint)
    report.guarded('Application-user workflow access',lambda:m.runtime_check(php,root,sorted(report.folders),report.readable,uid,account))
    return report


def provider_reads(s, m, root, php, account):
    # Existing code is hash-checked before execution. This bootstrap is process-local,
    # does not load PHP-FPM secrets and never enables booking_test_enabled().
    common = r'''
ini_set('display_errors','0');
putenv('SITESEE_REAL_ESTATE_SITE_URL=https://re.sitesee.ai');
putenv('SITESEE_REAL_ESTATE_PRICING_GATE_SECRET='.bin2hex(random_bytes(32)));
require $argv[1].'/server/booking-crm.php';
'''
    checks = {
        'Microsoft calendar and availability': lambda:s.fresh_read(m,root,php,account),
        'Zoho CRM identity and exact-email lookup': common + r'''
try { $c=booking_crm_config();$crm=booking_crm_client($c);booking_crm_verify_org($c,$crm);
 booking_crm_candidates('cro@sitesee.ai',$crm);echo 'PASS'; }
catch(Throwable $e){exit(1);}
''',
        'Dedicated invitation sender mailbox': common + r'''
try { $g=booking_graph_client(booking_mail_config(true));
 $r=$g('GET','/users/sales%40re.sitesee.ai/mailFolders/sentitems/messages?%24top=1&%24select=id');
 if($r['status']!==200 || !is_array($r['body']['value']??null))exit(1);echo 'PASS'; }
catch(Throwable $e){exit(1);}
''',
    }
    def run(value):
        if callable(value): value(); return
        p=subprocess.run([php,'-d','display_errors=0','-r',value,str(root)],preexec_fn=m.account_switch(account),
            stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=180)
        m.need(p.returncode==0 and p.stdout.strip()==b'PASS','Provider read did not complete.')
    # Sequential subprocesses avoid preexec_fn in a threaded process. Each outcome
    # is retained so one outage does not hide another independent blocker.
    failed=[]
    for label,value in checks.items():
        print('Checking '+label+' (read only)...',flush=True)
        try: run(value); print(label+': PASS',flush=True)
        except Exception: failed.append(label);print('REVIEW REQUIRED: '+label+' could not be verified; no provider writes were attempted.',flush=True)
    m.need(not failed,'Combined provider preflight did not pass: '+', '.join(failed)+'. Existing release remains installed; rerun this same installer after connection recovery.')


def desired(m, root, files):
    values={NAMES[0]:files[NAMES[0]]}
    for name in MANIFESTS[:2]:
        record=json.loads(m.private_bytes(root/name,root.stat().st_uid,private=False))
        record['files'].update({k:m.digest(v) for k,v in files.items()})
        values[name]=m.encode(record)
    values[MANIFESTS[-1]]=m.encode({'release':RELEASE,'revision':REVISION,'files':{k:m.digest(v) for k,v in files.items()}})
    # Existing Microsoft-capable staff controller is replaced only after its helper.
    values[CONTROLLER]=files[CONTROLLER]
    return values


def recover(m, root, uid, gid, check=False):
    path=m.safe_path(root,JOURNAL)
    if not path.exists(): return
    j=json.loads(m.private_bytes(path,uid))
    m.need(j.get('release')==RELEASE and j.get('revision')==REVISION and j.get('state') in ('prepared','installed','restored'),
        'Workflow recovery record differs; preserve it.')
    if j['state']!='prepared': return
    m.need(set(j.get('entries',{}))==set(NAMES+MANIFESTS) and re.fullmatch(r'booking-workflow-[A-Za-z0-9_-]+',j.get('backup','')),
        'Workflow recovery paths differ; preserve the journal.')
    folder=m.safe_path(root,'deployment-backups/'+j['backup'])
    originals={}
    for name, entry in j['entries'].items():
        target=m.safe_path(root,name)
        current=m.digest(m.private_bytes(target,uid,private=False)) if target.exists() else None
        m.need(current in (entry['old'],entry['new']),'Unrelated concurrent change preserved: '+name)
        old=m.private_bytes(folder/name,os.geteuid()) if entry['old'] is not None else None
        m.need(old is None or m.digest(old)==entry['old'],'Workflow backup integrity differs: '+name)
        originals[name]=old
    m.need(not check,'An interrupted workflow update needs recovery. Rerun this same installer without --check.')
    # Restore controller first. Keep the inert additive helper so any already-started
    # request running the new controller can finish while the old controller resumes.
    order=[CONTROLLER]+[n for n in originals if n!=CONTROLLER]
    for name in order:
        old=originals[name];target=root/name
        if old is not None: m.atomic_write(target,old,uid,gid)
        elif name!=NAMES[0] and target.exists(): target.unlink()
    j['state']='restored';m.atomic_write(path,m.encode(j),uid,gid)
    print('Interrupted workflow update recovered; Microsoft scheduling and booking records preserved.',flush=True)


def deploy(m,root,values,uid,gid,write=None):
    write=write or m.atomic_write
    if all((root/n).exists() and m.private_bytes(root/n,uid,private=False)==b for n,b in values.items()):return None
    base=m.safe_path(root,'deployment-backups')
    if not base.exists():base.mkdir(mode=0o700)
    m.need(base.is_dir() and not base.stat().st_mode&0o022,'Backup directory permissions differ.')
    folder=Path(tempfile.mkdtemp(prefix='booking-workflow-',dir=str(base)));entries={}
    for name,data in values.items():
        path=m.safe_path(root,name);old=m.private_bytes(path,uid,private=False) if path.exists() else None
        if old is not None:
            saved=folder/name;saved.parent.mkdir(mode=0o700,parents=True,exist_ok=True);m.atomic_write(saved,old,os.geteuid(),os.getegid())
        entries[name]={'old':m.digest(old) if old is not None else None,'new':m.digest(data)}
    j={'release':RELEASE,'revision':REVISION,'state':'prepared','backup':folder.name,'entries':entries}
    m.atomic_write(root/JOURNAL,m.encode(j),uid,gid)
    try:
        for name,data in values.items():
            path=m.safe_path(root,name);current=m.digest(m.private_bytes(path,uid,private=False)) if path.exists() else None
            m.need(current==entries[name]['old'],'Workflow target changed concurrently: '+name)
            write(path,data,uid,gid)
        for name,data in values.items():m.need(m.private_bytes(root/name,uid,private=False)==data,'Final workflow bytes differ: '+name)
        j['state']='installed';m.atomic_write(root/JOURNAL,m.encode(j),uid,gid)
    except Exception:
        recover(m,root,uid,gid)
        raise
    return folder


def main():
    s,r,m=modules();files,before=bundle(m)
    m.need(sys.argv[1:] in ([],['--check']),'Run with no arguments, or --check for local inspection.')
    m.need(os.geteuid()==0,'Run in WHM Terminal as root.')
    account=pwd.getpwnam('sitesee');uid,gid=account.pw_uid,account.pw_gid
    root,php=m.ROOT,m.PHP;os.umask(0o077);check=sys.argv[1:]==['--check']
    print('SiteSee TEST booking workflow | Revision: '+REVISION,flush=True)
    print('Installer SHA256: '+hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),flush=True)
    lock=os.open(str(root),os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW)
    try:
        fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
        m.need(not m.directory_check(root,uid,root=True),'Application root ownership or permissions differ; preserved for review.')
        recover(m,root,uid,gid,check)
        report=inventory(s,r,m,root,php,uid,files,before,account)
        r.show_inventory(report,lambda text:print(text,flush=True))
        m.need(not report.errors,'All independently detected local blockers are listed above. No installation was started.')
        if check:
            print('FINAL RESULTS\nWorkflow local inspection: PASS\nNo files, permissions or provider data changed.');return
        audit=r.apply_repairs(m,report,uid,gid)
        if audit:print('Permission recovery record: '+str(audit),flush=True)
        verified=inventory(s,r,m,root,php,uid,files,before,account)
        r.show_inventory(verified,lambda text:print(text,flush=True))
        m.need(not verified.errors and not verified.repairs,'Post-repair inventory changed. Retain the permission recovery record.')
        provider_reads(s,m,root,php,account)
        saved=deploy(m,root,desired(m,root,files),uid,gid)
        print('\nFINAL RESULTS\nStaff booking workflow: INSTALLED IN TEST MODE')
        print('Readiness, verified contact selection and combined recovery: installed')
        print('Microsoft calendar, dedicated sender and Zoho CRM read preflight: PASS')
        print('Active release hashes: PASS')
        print('No booking row, event, invitation, email, payment, credential content or integration setting was changed.')
        print('Microsoft scheduling and existing Zoho appointments: preserved')
        print('Actual new staff workflow and Microsoft invitation receipt/acceptance: require browser verification')
        print('Backup: '+str(saved) if saved else 'Existing workflow installation: unchanged')
        print('Next: refresh D32FFC7458. If already sent, use Recover Booking Status; do not resend.')
    finally:os.close(lock)


if __name__=='__main__':
    try:main()
    except Exception as e:
        print('\nFINAL RESULTS\nStaff booking workflow: STOPPED')
        print(str(e) if type(e).__name__=='InstallError' else 'A local/runtime check could not complete ('+type(e).__name__+').')
        print('Keep the workflow journal and backups. Rerun this same installer after review. Never restore a pre-Microsoft controller.')
        sys.exit(1)
